import * as THREE from './assets/three.module.js';
import {weatherKind} from './weather-tools.js';
export function mountWeatherArt(host,code,isDay=true){
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,20),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0,0);host.replaceChildren(renderer.domElement);renderer.domElement.setAttribute('aria-hidden','true');camera.position.set(0,1.3,7);camera.lookAt(0,0,0);scene.add(new THREE.AmbientLight(0xffffff,1.4));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(-3,5,5);scene.add(light);const blue=new THREE.DirectionalLight(0x93b5ff,1.4);blue.position.set(3,-2,3);scene.add(blue);
 const kind=weatherKind(code,isDay),cloud=['cloud','partly','rain','snow','storm'].includes(kind),sun=isDay&&['sun','partly'].includes(kind),sphere=new THREE.SphereGeometry(1,32,20);
 function ball(x,y,z,r,color){const mesh=new THREE.Mesh(sphere,new THREE.MeshPhysicalMaterial({color,roughness:.22,metalness:.03,clearcoat:.8}));mesh.position.set(x,y,z);mesh.scale.setScalar(r);scene.add(mesh);return mesh}
 if(sun){ball(cloud?-.6:0,cloud?.5:0,0,cloud?.58:.9,0xffc246);const center=new THREE.Vector3(cloud?-.6:0,cloud?.5:0,0);for(let i=0;i<10;i++){const a=i*Math.PI/5,r=cloud?.89:1.26;const ray=new THREE.Mesh(new THREE.CapsuleGeometry(.045,.18,3,8),new THREE.MeshStandardMaterial({color:0xffc653,roughness:.4}));ray.position.copy(center).add(new THREE.Vector3(Math.cos(a)*r,Math.sin(a)*r,0));ray.rotation.z=a-Math.PI/2;scene.add(ray)}}
 if(kind==='moon'||(kind==='partly'&&!isDay)){const shape=new THREE.Shape();shape.absarc(0,0,.85,.6,5.6,false);shape.quadraticCurveTo(-.05,-.18,.7,.48);const mesh=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:.2,bevelEnabled:true,bevelSize:.1,bevelThickness:.08,bevelSegments:3,steps:1,curveSegments:32}),new THREE.MeshStandardMaterial({color:0xc1d9ff,roughness:.24}));mesh.rotation.z=-.2;if(cloud){mesh.scale.setScalar(.75);mesh.position.set(-.6,.4,-.3)}scene.add(mesh)}
 if(cloud){for(const [x,y,z,r]of [[-.85,-.05,.3,.42],[-.38,.25,.1,.6],[.28,.42,.05,.66],[.83,.04,.28,.46],[.15,-.08,.4,.65]])ball(x,y,z,r,kind==='storm'?0xb7c5d7:0xf4f9ff)}
 if(['rain','snow','storm'].includes(kind)){for(let i=0;i<5;i++){const drop=ball(-.75+i*.37,-.9-(i%2)*.15,.25,.075,kind==='snow'?0xffffff:0x38a8f8);if(kind!=='snow'){drop.scale.set(.055,.18,.055);drop.rotation.z=-.3}}}
 if(kind==='storm'){const bolt=new THREE.Shape();bolt.moveTo(.14,-.55);bolt.lineTo(-.25,-1.12);bolt.lineTo(.08,-1.12);bolt.lineTo(-.08,-1.58);bolt.lineTo(.48,-.92);bolt.lineTo(.16,-.92);bolt.closePath();scene.add(new THREE.Mesh(new THREE.ExtrudeGeometry(bolt,{depth:.12,bevelEnabled:true,bevelSize:.035,bevelThickness:.03,bevelSegments:2}),new THREE.MeshStandardMaterial({color:0xffd44e,emissive:0x5d3000})))}
 const ro=new ResizeObserver(()=>{if(!host.isConnected)return;const w=host.clientWidth,h=host.clientHeight||220;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();renderer.render(scene,camera)});ro.observe(host);
 return()=>{ro.disconnect();const geometries=new Set();scene.traverse(o=>{if(o.geometry)geometries.add(o.geometry);o.material?.dispose()});geometries.forEach(g=>g.dispose());renderer.dispose();renderer.forceContextLoss();host.replaceChildren()};
}
